#include <stdio.h>
int isValid(char*s) {
    char stk[100];
    int t=-1;
    for (int i=0; s[i]; i++) {
        char c=s[i];
        if (c=='('||c=='['||c=='{')stk[++t]=c;
        else {
            if (t<0)return 0;
            char p=stk[t--];
            if ((c==')'&&p!='(')||(c==']'&&p!='[')||(c=='}'&&p!='{'))return 0;
        }
    }
    return t==-1;
}

